+package debugrepro_test
+
+import (
+	"context"
+	"fmt"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+func RunCli(args []string) {
+	cmd := &cli.Command{
+		Name:  "debug",
+		Usage: "make an explosive entrance",
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type Case struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+func Test_run(t *testing.T) {
+	t.Parallel()
+
+	tests := []Case{
+		{
+			Name: "hello_world",
+			Exit: 0,
+		},
+		{
+			Name: "hello_sunshine",
+			Exit: 0,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s", r, tt.Args)
+				}
+			}()
+
+			RunCli(tt.Args)
+		})
+	}
+}
diff --git a/debugrepro/stack_test.go b/debugrepro/stack_test.go
new file mode 100644
index 0000000..ef776b4
--- /dev/null
+++ b/debugrepro/stack_test.go
@@ -0,0 +1,26 @@
+package debugrepro_test
+
+import (
+	"runtime/debug"
+	"testing"
+)
+
+// Same as Test_run from the report, but prints the panic stack so the
+// faulting line is visible.
+func Test_runWithStack(t *testing.T) {
+	t.Parallel()
+
+	for _, name := range []string{"hello_world", "hello_sunshine"} {
+		t.Run(name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s'\n%s", r, debug.Stack())
+				}
+			}()
+
+			RunCli(nil)
+		})
+	}
+}
