--- /dev/null
+++ b/debugrepro/stress_test.go
@@ -0,0 +1,37 @@
+package debugrepro_test
+
+import (
+	"runtime/debug"
+	"sync"
+	"sync/atomic"
+	"testing"
+)
+
+// Higher-rate variant of the report's scenario: the same RunCli (no args, help
+// enabled by default) run from many goroutines at once instead of two.
+func Test_runStress(t *testing.T) {
+	var panics atomic.Int64
+	var first atomic.Value
+	var wg sync.WaitGroup
+	for g := 0; g < 8; g++ {
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			for i := 0; i < 20000; i++ {
+				func() {
+					defer func() {
+						if r := recover(); r != nil {
+							panics.Add(1)
+							first.CompareAndSwap(nil, string(debug.Stack()))
+						}
+					}()
+					RunCli(nil)
+				}()
+			}
+		}()
+	}
+	wg.Wait()
+	if n := panics.Load(); n > 0 {
+		t.Errorf("unexpected panic in %d of %d runs\nfirst stack:\n%v", n, 8*20000, first.Load())
+	}
+}
